"use client";

import * as React from "react";
import styles from "../styles/button-group.module.css";

export interface ButtonGroupProps {
  /** Option labels (each label is also its value) */
  options?: string[];
  /** Controlled selected option */
  value?: string;
  /** Initially selected option when uncontrolled (defaults to the second option) */
  defaultValue?: string;
  /** Called with the newly selected option */
  onValueChange?: (value: string) => void;
  /** Accessible name of the group */
  label?: string;
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Active indicator style */
  indicator?: "pill" | "solid" | "underline";
  /** Accent color for the solid / underline indicator */
  accentColor?: string;
  /** Stretch to fill the container, splitting options evenly */
  fullWidth?: boolean;
  /** Disable the whole group */
  disabled?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_OPTIONS = ["Daily", "Weekly", "Monthly", "Yearly"];
const useIsoLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

export function ButtonGroup({
  options = DEFAULT_OPTIONS,
  value: valueProp,
  defaultValue,
  onValueChange,
  label = "Reporting period",
  size = "md",
  indicator = "pill",
  accentColor = "#6366f1",
  fullWidth = false,
  disabled = false,
  className = "",
  style,
}: ButtonGroupProps) {
  const items = options.length > 0 ? options : DEFAULT_OPTIONS;
  const [inner, setInner] = React.useState(defaultValue ?? items[Math.min(1, items.length - 1)]);
  const value = valueProp !== undefined ? valueProp : inner;
  const activeIndex = items.indexOf(value);
  const listRef = React.useRef<HTMLDivElement>(null);
  const btnRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [box, setBox] = React.useState<{ x: number; w: number } | null>(null);
  const [animate, setAnimate] = React.useState(false);

  const select = (next: string) => {
    if (disabled || next === value) return;
    if (valueProp === undefined) setInner(next);
    onValueChange?.(next);
  };

  const measure = React.useCallback(() => {
    const el = btnRefs.current[activeIndex];
    setBox(el ? { x: el.offsetLeft, w: el.offsetWidth } : null);
  }, [activeIndex]);

  useIsoLayoutEffect(() => {
    measure();
  }, [measure, items.join("|"), size, fullWidth]);

  React.useEffect(() => {
    const id = requestAnimationFrame(() => setAnimate(true));
    const ro = typeof ResizeObserver !== "undefined" && listRef.current ? new ResizeObserver(() => measure()) : null;
    if (ro && listRef.current) ro.observe(listRef.current);
    return () => {
      cancelAnimationFrame(id);
      ro?.disconnect();
    };
  }, [measure]);

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const current = Math.max(0, btnRefs.current.findIndex((b) => b === document.activeElement));
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (current + 1) % items.length;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (current - 1 + items.length) % items.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = items.length - 1;
    if (next < 0) return;
    e.preventDefault();
    btnRefs.current[next]?.focus();
    select(items[next]);
  };

  const rootStyle = {
    "--mf-bgp-accent": accentColor,
    "--mf-bgp-x": box ? `${box.x}px` : "0px",
    "--mf-bgp-w": box ? `${box.w}px` : "0px",
    ...style,
  } as React.CSSProperties;

  return (
    <div
      ref={listRef}
      role="radiogroup"
      aria-label={label}
      aria-disabled={disabled || undefined}
      onKeyDown={onKeyDown}
      data-indicator={indicator}
      data-animate={animate || undefined}
      className={[styles.root, styles[size], fullWidth ? styles.full : "", className].filter(Boolean).join(" ")}
      style={rootStyle}
    >
      {box ? <span className={styles.indicator} aria-hidden="true" /> : null}
      {items.map((opt, i) => {
        const checked = i === activeIndex;
        const focusable = activeIndex === -1 ? i === 0 : checked;
        return (
          <button
            key={`${opt}-${i}`}
            ref={(el) => {
              btnRefs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={focusable ? 0 : -1}
            disabled={disabled}
            data-state={checked ? "on" : "off"}
            className={styles.item}
            onClick={() => select(opt)}
          >
            {opt}
          </button>
        );
      })}
    </div>
  );
}

.root {
  --mf-bgp-h: 2.25rem;
  position: relative;
  display: inline-flex;
  align-items: stretch;
  padding: 0.1875rem;
  gap: 0.125rem;
  border-radius: 0.625rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  isolation: isolate;
}

.sm {
  --mf-bgp-h: 1.875rem;
  font-size: 0.8125rem;
}

.md {
  --mf-bgp-h: 2.25rem;
  font-size: 0.875rem;
}

.lg {
  --mf-bgp-h: 2.625rem;
  font-size: 0.9375rem;
}

.full {
  display: flex;
  width: 100%;
}

.full .item {
  flex: 1 1 0;
}

.root[aria-disabled="true"] {
  opacity: 0.5;
}

.item {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: var(--mf-bgp-h);
  padding: 0 0.875em;
  border: 0;
  border-radius: 0.4375rem;
  background: transparent;
  color: var(--mf-muted, #a1a1aa);
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color 180ms ease, transform 160ms ease;
}

.item:hover:not(:disabled) {
  color: var(--mf-fg, #f4f4f6);
}

.item:active:not(:disabled) {
  transform: scale(0.97);
}

.item[data-state="on"] {
  color: var(--mf-fg, #f4f4f6);
}

.item:disabled {
  cursor: not-allowed;
}

.item:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 1px;
}

.indicator {
  position: absolute;
  z-index: 0;
  top: 0.1875rem;
  left: 0;
  height: var(--mf-bgp-h);
  width: var(--mf-bgp-w, 0px);
  transform: translateX(var(--mf-bgp-x, 0px));
  border-radius: 0.4375rem;
  background-color: var(--mf-surface-raised, #1b1b22);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25), inset 0 0 0 1px var(--mf-border, #2e2e38);
  pointer-events: none;
}

.root[data-animate] .indicator {
  transition: transform 320ms cubic-bezier(0.34, 1.32, 0.64, 1), width 320ms cubic-bezier(0.34, 1.32, 0.64, 1),
    background-color 200ms ease;
}

.root[data-indicator="solid"] .indicator {
  background-color: var(--mf-bgp-accent, #6366f1);
  box-shadow: 0 4px 14px -6px var(--mf-bgp-accent, #6366f1);
}

.root[data-indicator="solid"] .item[data-state="on"] {
  color: #ffffff;
}

.root[data-indicator="underline"] {
  border-color: transparent;
  background-color: transparent;
  border-radius: 0;
  box-shadow: inset 0 -1px 0 var(--mf-border, #2e2e38);
}

.root[data-indicator="underline"] .indicator {
  top: auto;
  bottom: 0;
  height: 2px;
  border-radius: 2px;
  background-color: var(--mf-bgp-accent, #6366f1);
  box-shadow: none;
}

@media (prefers-reduced-motion: reduce) {
  .item {
    transition: none;
  }

  .item:active:not(:disabled) {
    transform: none;
  }

  .root[data-animate] .indicator {
    transition: none;
  }
}

