"use client";

import { motion } from "motion/react";
import { useId, useRef, useState } from "react";

export function ButtonGroupTailwind({ options = ["Daily", "Weekly", "Monthly", "Yearly"] }) {
  const [value, setValue] = useState(options[1]);
  const id = useId();
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const onKeyDown = (e: React.KeyboardEvent) => {
    const i = options.indexOf(value);
    const n = e.key === "ArrowRight" ? (i + 1) % options.length : e.key === "ArrowLeft" ? (i - 1 + options.length) % options.length : -1;
    if (n < 0) return;
    e.preventDefault();
    setValue(options[n]);
    refs.current[n]?.focus();
  };
  return (
    <div role="radiogroup" aria-label="Reporting period" onKeyDown={onKeyDown} className="inline-flex gap-0.5 rounded-xl border border-zinc-800 bg-zinc-900 p-[3px]">
      {options.map((o, i) => (
        <button key={o} ref={(el) => { refs.current[i] = el; }} type="button" role="radio" aria-checked={o === value} tabIndex={o === value ? 0 : -1} onClick={() => setValue(o)} className={`relative h-9 rounded-lg px-3.5 text-sm font-medium ${o === value ? "text-zinc-100" : "text-zinc-400 hover:text-zinc-100"}`}>
          {o === value && <motion.span layoutId={id} transition={{ type: "spring", stiffness: 500, damping: 34 }} className="absolute inset-0 rounded-lg bg-zinc-800 ring-1 ring-zinc-700" />}
          <span className="relative">{o}</span>
        </button>
      ))}
    </div>
  );
}
